import sendIcon from '../../assets/send_icon.svg';
import softyAvatar from '../../assets/softy.svg';
import documentIcon from '../../assets/document.svg';
import cloudIcon from '../../assets/cloud_ok.svg';

type Message = {
  message: ReactNode;
  is_answer: boolean;
  created: string;
};

const initialChat: { messages: Message[] } = { messages: [] };

export const AssistantComponent = (profile: ProfileInfo) => {
  const [messages, setMessages] = useState(initialChat);
  const [messageText, setMessageText] = useState('');
  const [isBotTyping, setIsBotTyping] = useState(false);
  const messagesEndRef = useRef<HTMLDivElement>(null);

  const handleSendClick = async () => {
    if (!messageText.trim()) return;

    const timestamp = new Date().toLocaleString();
    const newUserMessage = {
      message: messageText,
      is_answer: false,
      created: timestamp,
    };

    setMessages((prev) => ({
      messages: [...prev.messages, newUserMessage],
    }));

    setMessageText('');
    setIsBotTyping(true);

    try {
      const response = await fetch(`http://localhost:7007/api/softy-service-desk/generative-request`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ prompt: messageText }),
      });

      if (!response.ok) {
        throw new Error(`HTTP error! Status: ${response.status}`);
      }

      const { answer = '' } = await response.json();

      setMessages((prev) => ({
        messages: [
          ...prev.messages,
          { message: answer, is_answer: true, created: timestamp },
        ],
      }));
    } catch (error) {
      console.error('Error fetching generative request:', error);
    } finally {
      setIsBotTyping(false);
    }
  };

  useEffect(() => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  }, [messages]);

  let lastDate: string | null = null;
  const today = new Date();

  return (
