      <div style={{ height: '76dvh', overflowY: 'scroll' }}>
        <List>
          {messages.messages.length === 0 ? (
            <Grid container spacing={3} justifyContent="center">
              <Grid item>
                <Card style={{ width: '25rem', color: '#0055A0' }}>
                  <CardContent>
                    <Box
                      display="flex"
                      flexDirection="column"
                      alignItems="center"
                    >
                      <img
