                        {[
                          'Quiero saber como el usuario puede lograr...',
                          '¿Bajo que nube se encuentra el aplicativo?',
                          '¿Han habido incidencias similares para el aplicativo?',
                          'Tengo un caso que no puedo resolver, ¿qué puedo hacer?',
                        ].map((item, index) => (
                          <Box
                            key={index}
                            color="black"
                            bgcolor="#F8F7FC"
                            p={1}
                            mb={3}
                            borderRadius={4}
                          >
                            <Typography variant="body2">{item}</Typography>
                          </Box>
                        ))}
                      </Box>
                    </Box>
                  </CardContent>
                </Card>
              </Grid>
              <Grid item>
                <Card style={{ width: '25rem', color: '#0055A0' }}>
                  <CardContent>
                    <Box
                      display="flex"
                      flexDirection="column"
                      alignItems="center"
                    >
                      <img
                        src={documentIcon}
                        alt="No messages icon 2"
                        style={{ width: '50px', height: '50px' }}
                      />
                      <Typography variant="h5" align="center">
                        Quiero saber como funciona <br /> un aplicativo
                      </Typography>
                      <Box mt={2}>
                        {[
                          'Como puede el usaurio cambiar su clave',
                          'Para qué dispositivos está disponible el app',
                          'Qué polizas abarca el servicio salud',
                          'Como puede el usuario exportar un documento',
                        ].map((item, index) => (
                          <Box
                            key={index}
                            color="black"
                            bgcolor="#F8F7FC"
                            width="100%"
                            p={1}
                            mb={3}
                            borderRadius={4}
                          >
                            <Typography variant="body2">{item}</Typography>
                          </Box>
                        ))}
                      </Box>
                    </Box>
                  </CardContent>
                </Card>
              </Grid>
            </Grid>
          ) : (
            <>
              {messages.messages.map((message, index) => {
                const messageDate = new Date(Date.parse(message.created));
                const utcMessageDate =
                  today.getUTCDate() === messageDate.getUTCDate()
                    ? 'Hoy'
