                  title="Quiero saber como funciona un aplicativo"
                  suggestions={[
                    'Como puede el usaurio cambiar su clave',
                    'Para qué dispositivos está disponible el app',
                    'Qué polizas abarca el servicio salud',
                    'Como puede el usuario exportar un documento',
                  ]}
                />
              </Grid>
            </Grid>
          ) : (
            <>
              {messages.messages.map((message, index) => {
                const messageDate = new Date(Date.parse(message.created));
                const utcMessageDate =
                  today.getUTCDate() === messageDate.getUTCDate()
                    ? 'Hoy'
                    : new Date(
                        messageDate.getUTCFullYear(),
                        messageDate.getUTCMonth(),
                        messageDate.getUTCDate(),
                      ).toLocaleDateString();

                const showDate = lastDate !== utcMessageDate;
                lastDate = utcMessageDate;

                return (
                  <React.Fragment key={index}>
                    {showDate && (
                      <ListItem>
                        <Box
                          display="flex"
                          justifyContent="center"
                          alignItems="center"
                          style={{ width: '100%' }}
                        >
                          <Box
                            style={{
                              color: '#8a8a8a',
                              padding: '.5rem',
                              borderRadius: '1rem',
                            }}
                          >
                            {utcMessageDate}
                          </Box>
                        </Box>
                      </ListItem>
                    )}

                    {message.is_answer ? (
                      <AssistantMessage message={message} />
                    ) : (
                      <UserMessage message={message} profile={profile} />
                    )}
                  </React.Fragment>
                );
              })}

              {isBotTyping && (
                <AssistantMessage
                  message={{
                    message: (
                      <Box display="flex" alignItems="center">
                        <CircularProgress size={20} style={{ marginRight: '0.5rem' }} />
                        <Typography variant="body2">Softy está escribiendo...</Typography>
                      </Box>
                    ),
                    is_answer: true,
                    created: new Date().toLocaleString(),
                  }}
                />
              )}
            </>
          )}
          <div ref={messagesEndRef} />
        </List>
      </div>

      <MessageInput
        messageText={messageText}
        setMessageText={setMessageText}
        handleSendClick={handleSendClick}
        isBotTyping={isBotTyping}
      />
    </Box>
  );
};
